import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), k = (int) nextLong(), m = (int) nextLong();
        int[] board = new int[n * n];
        long occupied = 0;
        boolean winner = false;
        int[][] dirs = {{1, 0}, {0, 1}, {1, 1}, {1, -1}};
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < m; t++) {
            int player = (int) nextLong(), r = (int) nextLong(), c = (int) nextLong();
            if (winner) { out.append("Game Over\n"); continue; }
            if (board[r * n + c] != 0) { out.append("Invalid Move\n"); continue; }
            board[r * n + c] = player;
            occupied++;
            // a new line of three must pass through this cell: look up to 2 cells each way
            for (int[] d : dirs) {
                int count = 1;
                for (int dir = -1; dir <= 1; dir += 2)
                    for (int step = 1; step <= 2; step++) {
                        int a = r + dir * step * d[0], b = c + dir * step * d[1];
                        if (a < 0 || a >= n || b < 0 || b >= n || board[a * n + b] != player) break;
                        count++;
                    }
                if (count >= 3) winner = true;
            }
            if (winner) out.append("Player ").append(player).append(" won\n");
            else out.append(occupied == (long) n * n ? "Draw\n" : "In Progress\n");
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, _, m := nextInt(), nextInt(), nextInt()
	board := make([]int, n*n)
	occupied := 0
	winner := false
	dirs := [4][2]int{{1, 0}, {0, 1}, {1, 1}, {1, -1}}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for t := 0; t < m; t++ {
		player, r, c := nextInt(), nextInt(), nextInt()
		if winner {
			w.WriteString("Game Over\n")
			continue
		}
		if board[r*n+c] != 0 {
			w.WriteString("Invalid Move\n")
			continue
		}
		board[r*n+c] = player
		occupied++
		// a new line of three must pass through this cell: look up to 2 cells each way
		for _, d := range dirs {
			count := 1
			for _, dir := range [2]int{-1, 1} {
				for step := 1; step <= 2; step++ {
					a, b := r+dir*step*d[0], c+dir*step*d[1]
					if a < 0 || a >= n || b < 0 || b >= n || board[a*n+b] != player {
						break
					}
					count++
				}
			}
			if count >= 3 {
				winner = true
			}
		}
		if winner {
			w.WriteString("Player " + strconv.Itoa(player) + " won\n")
		} else if occupied == n*n {
			w.WriteString("Draw\n")
		} else {
			w.WriteString("In Progress\n")
		}
	}
}
